#' Inject controlled violations into admissible routing data
#'
#' @param data Admissible data generated by `generate_admissible_records()`.
#' @param dag An SSPICE DAG object.
#' @param id_col Name of the record identifier column.
#' @param items_mapping_file Optional path to `items_mapping.csv`.
#' @param proportion Proportion of records to alter.
#' @param seed Random seed.
#' @return A list with altered data and record-level ground truth.
#' @keywords internal
inject_routing_violations <- function(
  data,
  dag,
  id_col,
  items_mapping_file = NULL,
  proportion = 0.5,
  seed = 123L
) {
  if (!id_col %in% names(data)) {
    stop("id_col is absent from data.", call. = FALSE)
  }
  if (!is.numeric(proportion) || proportion < 0 || proportion > 1) {
    stop("proportion must be between zero and one.", call. = FALSE)
  }

  set.seed(seed)
  routes <- dag$routes_numeric
  varnames <- as.character(dag$varnames)
  Bt <- as.matrix(dag$Bt)
  domains <- .sspice_synthetic_domains(routes, varnames, items_mapping_file)
  rows_by_source <- .sspice_bt_rows_by_source(domains, nrow(Bt))
  altered <- data
  number_to_alter <- as.integer(round(nrow(data) * proportion))
  selected <- if (number_to_alter) sample(seq_len(nrow(data)), number_to_alter) else integer()

  truth <- data.frame(
    record_id = data[[id_col]],
    is_violated = FALSE,
    injected_var = NA_character_,
    injection_type = NA_character_,
    original_value = NA_character_,
    injected_value = NA_character_,
    stringsAsFactors = FALSE
  )

  for (record_index in selected) {
    candidates <- .sspice_injection_candidates(
      altered[record_index, , drop = FALSE], routes, varnames, Bt,
      domains, rows_by_source, id_col
    )
    if (!nrow(candidates)) next
    chosen <- candidates[sample(seq_len(nrow(candidates)), 1L), , drop = FALSE]
    variable <- chosen$variable
    old_value <- altered[[variable]][record_index]
    new_value <- if (chosen$type == "REMOVE_REQUIRED_VALUE") {
      NA_real_
    } else {
      sample(domains[[match(variable, varnames)]]$data, 1L)
    }
    altered[[variable]][record_index] <- new_value
    truth$is_violated[record_index] <- TRUE
    truth$injected_var[record_index] <- variable
    truth$injection_type[record_index] <- chosen$type
    truth$original_value[record_index] <- as.character(old_value)
    truth$injected_value[record_index] <- as.character(new_value)
  }

  names(truth)[1L] <- id_col
  list(data = altered, ground_truth = truth)
}

.sspice_injection_candidates <- function(
  record, routes, varnames, Bt, domains, rows_by_source, id_col
) {
  candidates <- list()
  cursor <- 0L
  for (source in seq_along(varnames)) {
    modal_rows <- rows_by_source[[source]]
    value <- record[[varnames[source]]][1L]
    if (!length(modal_rows) || is.na(value)) next
    position <- match(as.character(value), as.character(domains[[source]]$data))
    if (is.na(position)) position <- 1L
    edge <- Bt[modal_rows[position], ]
    from <- which(edge == 1L)
    targets <- which(edge == -1L)

    for (target in targets) {
      if (varnames[target] != id_col && !is.na(routes[target, 3L]) &&
          !is.na(record[[varnames[target]]][1L])) {
        cursor <- cursor + 1L
        candidates[[cursor]] <- data.frame(
          variable = varnames[target], type = "REMOVE_REQUIRED_VALUE",
          stringsAsFactors = FALSE
        )
      }
      between <- if (target > from + 1L) seq.int(from + 1L, target - 1L) else integer()
      blank_nodes <- between[edge[between] == 0L]
      blank_nodes <- blank_nodes[
        varnames[blank_nodes] != id_col &
          vapply(blank_nodes, function(x) is.na(record[[varnames[x]]][1L]), logical(1L))
      ]
      for (blank in blank_nodes) {
        cursor <- cursor + 1L
        candidates[[cursor]] <- data.frame(
          variable = varnames[blank], type = "FILL_SKIPPED_VALUE",
          stringsAsFactors = FALSE
        )
      }
    }
  }
  if (!length(candidates)) {
    return(data.frame(variable = character(), type = character()))
  }
  unique(do.call(rbind, candidates))
}
